import { RESULT_CODES, ResultCode, ResultCodeData } from '@game-studio/server-comms';
import { IGlobalEvents } from '../services/events';

export type ErrorState = 'HANDLED' | 'UNHANDLED';
type HandledError = {
    /**
    * Optional GlobalEvent to call once the game has initialised (For handled errors)
    */
    eventKey?: keyof IGlobalEvents
};
type HandledErrorMap = {
    [key in ResultCode]?: HandledError
};

/**
 * Leave object empty if the handled error result code doesnt call an event
 */
const handledErrors: HandledErrorMap = {
    [RESULT_CODES.ACCOUNT_FAILURE]: { eventKey: 'GLOBAL_ACCOUNT_LOCKED' },
};

export class BootstrapErrorModel {
    /**
    * Unhandled error, will show a bootstrap error overlay prompting player to close the window, uses error strings
    * If its a resume error, the error code will be used to lookup a display string from the errorStrings.json
    * Handled error, will allow player through to the game, we consider some resume error codes handled as there's a nicer
    * way to display to the player on the game
    */
    public error: boolean = false;

    public resumeErrorResultCode?: ResultCodeData;
    /**
    * Check for either type of error, to disable anything in game we wouldnt want to show or action we'd want to prevent
    */
    public get hasErrored(): boolean {
        return this.errorState !== void (0);
    }

    public get handledErrorEventCall(): keyof IGlobalEvents | undefined {
        if (!this.resumeErrorResultCode?.ResultCode) {
            return;
        }
        return this.handledError?.eventKey;
    }

    public get errorState(): ErrorState | undefined {
        if (!this.error) {
            return;
        }
        return this.handledError !== void (0) ? 'HANDLED' : 'UNHANDLED';
    }

    private get handledError(): HandledError | undefined {
        if (!this.resumeErrorResultCode?.ResultCode) {
            return;
        }
        return handledErrors[this.resumeErrorResultCode.ResultCode];
    }
}

export const bootstrapErrorModel = new BootstrapErrorModel();
